from typing import List

def merge_sorted_lists(left: List[int], right: List[int]) -> List[int]):
    """Merges two sorted lists of integers into one sorted list.

    Args:
        left: A sorted list of integers.
        right: Another sorted list of integers.

    Returns: A new sorted list containing all elements from both input lists.

    Example:
        >>> merge_sorted_lists([1, 3, 5], [2, 4, 6]), [1, 2, 3, 4, 5, 6])
        True
    """
    if not left or not right:
        return left or right
    if left[0] < right[0]: 
        return [left[0]] + merge_sorted_lists(left[1:], right) 
    else: 
        return [right[0]] + merge_sorted_lists(left, right[1:]) 
} 
