def get_top_n_frequent_words(text: str, n: int) -> dict:
    """Return the n most frequent words in a text string.

    Args:
        text: The text to analyze.
        n: The number of top frequent words to return.

    Returns:
        A dictionary containing the top n most frequent words and their counts.

    Example:
        >>> get_top_n_frequent_words("hello world hello", 2)
        {'hello': 2}
    """
    if not text or n < 0:
        raise ValueError("text must be a non-empty string and n must be a non-negative integer")

    words = text.split()
    word_counts = {}
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1

    sorted_word_counts = sorted(word_counts.items(), key=lambda item: (-item[1], item[0]))
    top_n_words = {word: count for word, count in sorted_word_counts[:n]}

    return top_n_words
