from typing import List, Any

def flatten(nested_list: List[Any]) -> List[int]:
    """Flatten a nested list of integers."""
    flat_list = []
    for item in nested_list:
        if isinstance(item, int):
            flat_list.append(item)
        else:
            flat_list.extend(flatten(item))
