def flatten(nested_list: list[list[int]]) -> list[int]:
    """Flatten a nested list of integers of arbitrary depth.

    Args:
        nested_list: A nested list of integers of arbitrary depth.

    Returns:
        A flattened list of integers.

    Example:
        >>> flatten([[1, 2], [3, [4, 5]], 6])
        [1, 2, 3, 4, 5, 6]
    """
    def _flatten(lst):
        for el in lst:
            if isinstance(el, list):
                yield from _flatten(el)
            else:
                yield el

    return list(_flatten(nested_list))
